def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    opp_d = 0
    my_d = 0
    unprovoked_d = 0

    for i, pair in enumerate(history):
        m, o = pair
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1
            if i == 0 or history[i - 1][0] == 'C':
                unprovoked_d += 1

    rem = 100 - n
    if rem <= 1:
        return 'D'

    start = n - 10
    if start < 0:
        start = 0

    recent_opp_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_opp_d += 1

    last_D = -1
    last_response = None
    for i in range(n):
        if history[i][0] == 'D':
            last_D = i
            if i + 1 < n:
                last_response = history[i + 1][1]

    exploitable = (last_response == 'C')

    high_d = False
    if n >= 2 and opp_d == n:
        high_d = True
    if n >= 8 and opp_d >= n - 2:
        high_d = True
    if recent_opp_d >= 8:
        high_d = True
    if n >= 20 and opp_d * 5 >= n * 3 and recent_opp_d >= 5:
        high_d = True
    if n >= 12 and unprovoked_d >= max(3, n // 8) and unprovoked_d * 2 >= opp_d:
        high_d = True

    if rem <= 4:
        if high_d:
            return 'D'

        if opp_last == 'C':
            if exploitable and opp_d <= max(4, n // 4):
                return 'D'
            if opp_d == 0 and my_d > 0 and last_response == 'C':
                return 'D'
            return 'C'

        unprovoked_last = (n == 1 or history[-2][0] == 'C')
        if unprovoked_last:
            return 'D'

        if opp_d <= max(4, n // 4) and unprovoked_d <= max(3, n // 5):
            return 'C'
        return 'D'

    if high_d:
        return 'D'

    if opp_d == 0:
        if my_d == 0:
            if n >= 8:
                return 'D'
            return 'C'

        if last_response == 'C':
            return 'D'

        if my_last == 'D':
            return 'C'

        return 'D'

    if exploitable and opp_last == 'C' and opp_d <= max(4, n // 4):
        return 'D'

    if (
        not exploitable
        and opp_d <= 1
        and recent_opp_d == 0
        and my_last == 'C'
        and opp_last == 'C'
        and n >= 60
    ):
        return 'D'

    if my_last == 'D' and opp_last == 'C' and not exploitable:
        return 'C'

    if opp_last == 'C':
        return 'C'

    if n == 1 or (n >= 2 and history[-2][0] == 'C'):
        return 'D'

    if opp_d <= max(4, n // 4) and unprovoked_d <= max(3, n // 5):
        return 'C'

    return 'D'
